const methodOverrides: Record<string,RecipeVersion['steps']> = {
  yukishiro:S(['Spray the glass side with Kanade Yuzu and coat it with granulated sugar; make a lemon-and-matcha snow rim. Shake the drink, strain through a chinois, and open a desalted salt-pickled sakura blossom in the glass.'],['杯侧喷奏柚子并裹细砂糖，再以柠檬与抹茶做雪边；材料加冰摇匀，经细筛滤入杯中，放入脱盐的盐渍樱花使其展开。'],['Vaporiser le verre de Kanade Yuzu et sucrer; faire un bord citron-matcha, shaker, filtrer au chinois et ajouter la fleur de sakura dessalée.'],['Glasseite mit Kanade Yuzu besprühen und zuckern; Zitronen-Matcha-Rand, shaken, fein abseihen und entsalzte Sakurablüte öffnen.'],['Rocía Kanade Yuzu y azucara el lateral; prepara borde de limón y matcha, agita, cuela fino y abre la flor de sakura desalinizada.'],['잔 옆면에 가나데 유자를 뿌려 설탕을 묻히고 레몬·말차 스노 림을 만듭니다. 셰이크해 고운 체로 거르고 염분을 뺀 사쿠라 절임을 펼칩니다.'],['グラス側面に奏〈柚子〉をスプレーしてグラニュー糖をまぶし、レモンと抹茶でスノースタイルにする。シェークしてシノワでこし、塩抜きした桜塩漬けを開かせます。'],['Spruzzare Kanade Yuzu e zuccherare il lato; creare bordo limone-matcha, shakerare, filtrare e aprire il sakura dissalato.']),
  atarayo:S(['Shake everything except Akadama Sweet Wine with ice and strain into a cocktail glass; float the wine and add the stated garnish.'],['除赤玉甜红酒外所有材料加冰摇匀，滤入鸡尾酒杯；漂浮甜红酒并按来源装饰。'],['Shaker sauf l’Akadama, filtrer en verre à cocktail, faire flotter le vin et garnir.'],['Alles außer Akadama shaken und abseihen; Wein floaten und garnieren.'],['Agita salvo Akadama, cuela, flota el vino y decora.'],['아카다마를 제외하고 셰이크해 거른 뒤 와인을 띄우고 장식합니다.'],['赤玉スイートワイン以外をシェークして注ぎ、赤玉をフロートして飾ります。'],['Shakerare salvo Akadama, filtrare, far galleggiare il vino e guarnire.']),
  suehiro:S(['Shake with ice and strain into a cocktail glass. Slap the kinome to release its aroma and float it, then add the remaining stated garnish.'],['加冰摇匀滤入鸡尾酒杯；拍打木之芽释放香气后浮于酒面，再完成其余装饰。'],['Shaker et filtrer; claquer le kinome, le faire flotter et ajouter les autres garnitures.'],['Shaken und abseihen; Kinome anschlagen, floaten und weitere Garnitur zufügen.'],['Agita y cuela; golpea el kinome, flótalo y añade las demás guarniciones.'],['셰이크해 거른 뒤 기노메를 쳐 향을 내고 띄운 다음 나머지 장식을 더합니다.'],['シェークして注ぎ、木の芽を叩いて香りを立たせて浮かべ、ほかの飾りを添えます。'],['Shakerare e filtrare; battere il kinome, farlo galleggiare e aggiungere le altre guarnizioni.']),
  braver:S(['Shake everything except Hermes Green Tea with ice and strain into a cocktail glass; sink the green-tea liqueur and garnish.'],['除 Hermes 绿茶利口酒外所有材料加冰摇匀并滤入杯中；将绿茶利口酒沉底并装饰。'],['Shaker sauf le Hermes Green Tea, filtrer, faire couler la liqueur de thé et garnir.'],['Alles außer Hermes Green Tea shaken und abseihen; Teelikör sinken lassen und garnieren.'],['Agita salvo Hermes Green Tea, cuela, hunde el licor de té y decora.'],['헤르메스 그린티를 제외하고 셰이크해 거른 뒤 그린티 리큐어를 가라앉히고 장식합니다.'],['ヘルメス グリーンティ以外をシェークして注ぎ、グリーンティを沈めて飾ります。'],['Shakerare salvo Hermes Green Tea, filtrare, far affondare il liquore e guarnire.']),
};

