const flavourWords: Record<string,Localized> = {
  citrus:L('citrus','柑橘','agrumes','Zitrus','cítricos','시트러스','柑橘','agrumi'), fruit:L('fruit','果香','fruit','Frucht','fruta','과일','果実','frutta'),
  floral:L('floral','花香','floral','blumig','floral','꽃','花','floreale'), herbal:L('herbal or tea-led','草本或茶香','herbacé ou au thé','Kräuter oder Tee','herbal o de té','허브 또는 차','ハーブまたは茶','erbaceo o al tè'),
  spice:L('spice','辛香','épices','Würze','especias','향신료','スパイス','spezie'), coffee:L('coffee','咖啡','café','Kaffee','café','커피','コーヒー','caffè'),
};
const contestDescription=(d:Draft):Localized=>{
  const meta=contestMeta[d.id]!;
  const f=d.flavours.map(x=>flavourWords[x]);
  const fv=(locale:keyof Localized)=>f.map(x=>x![locale]).join(' / ');
  return L(`${d.name.en}, a ${d.year} Suntory finalist by ${meta.bartender} of ${meta.bar}; editorial profile: ${fv('en')}.`,`${d.name.zh}：${meta.bartender}（${meta.bar}）的 ${d.year} 年三得利决赛创作；编辑风味：${fv('zh')}。`,`Finaliste Suntory ${d.year} de ${meta.bartender}, ${meta.bar}; profil éditorial : ${fv('fr')}.`,`Suntory-Finaldrink ${d.year} von ${meta.bartender}, ${meta.bar}; Profil: ${fv('de')}.`,`Finalista Suntory ${d.year} de ${meta.bartender}, ${meta.bar}; perfil: ${fv('es')}.`,`${meta.bar}의 ${meta.bartender}가 만든 ${d.year} 산토리 결선작; 편집 풍미: ${fv('ko')}.`,`${meta.bar}の${meta.bartender}による${d.year}年サントリー・ファイナル作品。編集風味：${fv('ja')}。`,`Finalista Suntory ${d.year} di ${meta.bartender}, ${meta.bar}; profilo: ${fv('it')}.`);
};
const sources: Source[] = [...baseSources,...drafts.filter(d=>d.year).map(d=>({id:`batch-h-${d.id}`,title:`${d.name.ja} — Suntory ${d.year} official recipe`,url:`https://www.suntory.co.jp/wnb/event/award/result_${d.year}.html`,author:`${contestMeta[d.id]!.bartender} — ${contestMeta[d.id]!.bar}`,checkedAt}))];

const sourceLabel=(d:Draft)=>d.year?contestLabel:d.sourceId.startsWith('hos-')?houseLabel:historyLabel;
const versions: RecipeVersion[] = drafts.map(d=>{
  const originalLanguage = d.year || d.sourceId==='suntory-million-dollar' ? 'ja' : 'en';
  const steps = methodOverrides[d.id]??d.steps??shakeUp;
  return {id:`${d.id}-batch-h`,cocktailId:d.id,label:sourceLabel(d),sourceId:d.year?`batch-h-${d.id}`:d.sourceId,servings:1,ingredients:d.ingredients,steps,originalLanguage,originalSteps:d.originalSteps??steps[originalLanguage],glass:d.glass??cocktailGlass,garnish:d.garnish,flavours:d.flavours,tastes:d.tastes,strength:d.strength,approachability:d.strength==='strong'?'bold':'balanced',profileBasis:'editorial',profileNote:d.year?contestDescription(d):(d.description??genericDescription),sourceChecked:true,translationStatus:'draft'};
});
const cocktails: Cocktail[] = drafts.map(d=>({id:d.id,name:d.name,aliases:[...new Set([...(d.aliases??[]),...(japaneseSearchAliases[d.id]??[])])],category:d.category??'curated',collections:['japan'],description:d.year?contestDescription(d):(d.description??genericDescription),versionIds:[`${d.id}-batch-h`],defaultVersionId:`${d.id}-batch-h`,accent:d.year===2025?'#6F7E69':d.year===2024?'#B46D73':d.year===2023?'#9A744C':'#6C7F86'}));

export const batchH: CatalogueBatch = {cocktails,versions,sources,ingredients,brands};
export default batchH;
